```html id="m2k7qw"
<style>
    *{
        margin:0;
        padding:0;
        box-sizing:border-box;
    }

    body{
        font-family:Arial, sans-serif;
        background:#f4f6f8;
        color:#1c1c1c;
        line-height:1.7;
    }

    .container{
        max-width:1320px;
        margin:0 auto;
        padding:0 20px;
    }

    section{
        padding:80px 0;
    }

    h1,h2,h3{
        font-weight:700;
        line-height:1.2;
    }

    h1{
        font-size:54px;
        margin-bottom:24px;
    }

    h2{
        font-size:38px;
        margin-bottom:40px;
    }

    h3{
        font-size:22px;
        margin-bottom:16px;
    }

    p{
        font-size:16px;
        color:#555;
    }

    /* HERO */

    .hero{
        background:#111;
        color:#fff;
        border-radius:32px;
        overflow:hidden;
        margin:20px;
    }

    .hero-wrapper{
        display:grid;
        grid-template-columns:1fr 1fr;
        gap:60px;
        align-items:center;
        padding:100px 80px;
    }

    .hero p{
        color:#ccc;
        margin-bottom:32px;
    }

    .hero-tags{
        display:flex;
        flex-wrap:wrap;
        gap:12px;
        margin-bottom:40px;
    }

    .hero-tags span{
        background:#222;
        padding:12px 18px;
        border-radius:12px;
        font-size:14px;
        border:1px solid #333;
    }

    .btn{
        display:inline-block;
        padding:18px 32px;
        background:#ff6b00;
        color:#fff;
        text-decoration:none;
        border-radius:12px;
        font-weight:700;
        transition:0.3s;
    }

    .btn:hover{
        opacity:0.9;
    }

    .hero-image{
        background:#1d1d1d;
        border-radius:24px;
        min-height:500px;
    }

    /* TILE GRID */

    .tile-grid{
        display:grid;
        grid-template-columns:repeat(2,1fr);
        gap:24px;
    }

    .tile{
        background:#fff;
        border-radius:28px;
        padding:40px;
        box-shadow:0 10px 30px rgba(0,0,0,0.05);
        transition:0.3s;
    }

    .tile:hover{
        transform:translateY(-5px);
    }

    .tile.large{
        grid-column:span 2;
    }

    /* ADVANTAGES */

    .advantages-grid{
        display:grid;
        grid-template-columns:repeat(4,1fr);
        gap:24px;
    }

    .advantage-card{
        background:#fff;
        padding:32px;
        border-radius:24px;
        box-shadow:0 10px 30px rgba(0,0,0,0.05);
    }

    /* APPLICATION */

    .application-grid{
        display:grid;
        grid-template-columns:repeat(3,1fr);
        gap:20px;
    }

    .application-item{
        background:#fff;
        padding:28px;
        border-radius:20px;
        text-align:center;
        font-weight:600;
        box-shadow:0 8px 25px rgba(0,0,0,0.04);
    }

    /* TABLE */

    .specs-table{
        width:100%;
        border-collapse:collapse;
        overflow:hidden;
        border-radius:20px;
    }

    .specs-table tr{
        background:#fff;
    }

    .specs-table td{
        padding:22px 30px;
        border-bottom:1px solid #eee;
    }

    .specs-table td:first-child{
        font-weight:700;
        width:40%;
    }

    /* VIDEO */

    .video-box{
        height:500px;
        background:#ddd;
        border-radius:28px;
        display:flex;
        align-items:center;
        justify-content:center;
        color:#666;
        font-size:20px;
    }

    /* FAQ */

    .faq-list{
        display:grid;
        gap:20px;
    }

    .faq-item{
        background:#fff;
        padding:32px;
        border-radius:22px;
        box-shadow:0 10px 25px rgba(0,0,0,0.04);
    }

    /* CTA */

    .cta{
        background:#111;
        border-radius:32px;
        color:#fff;
        text-align:center;
        padding:100px 40px;
    }

    .cta p{
        color:#bbb;
        max-width:700px;
        margin:20px auto 40px;
    }

    /* RESPONSIVE */

    @media(max-width:992px){

        .hero-wrapper{
            grid-template-columns:1fr;
        }

        .advantages-grid{
            grid-template-columns:1fr 1fr;
        }

        .application-grid{
            grid-template-columns:1fr 1fr;
        }

        .tile-grid{
            grid-template-columns:1fr;
        }

        .tile.large{
            grid-column:span 1;
        }
    }

    @media(max-width:768px){

        h1{
            font-size:38px;
        }

        h2{
            font-size:30px;
        }

        .advantages-grid,
        .application-grid{
            grid-template-columns:1fr;
        }

        .hero-wrapper{
            padding:60px 30px;
        }

        .tile{
            padding:28px;
        }
    }
</style>

<!-- HERO -->
<section class="hero">
    <div class="hero-wrapper">

        <div>
            <h1>Промышленный SLM 3D-принтер AMT</h1>

            <p>
                Высокопроизводительное решение для металлической 3D-печати 
                изделий сложной геометрии для промышленного производства.
            </p>

            <div class="hero-tags">
                <span>SLM технология</span>
                <span>Многолазерная система</span>
                <span>Печать металлом</span>
                <span>Промышленный класс</span>
            </div>

            <a href="#" class="btn">Запросить консультацию</a>
        </div>

        <div class="hero-image"></div>

    </div>
</section>

<div class="container">

    <!-- ПРЕИМУЩЕСТВА -->
    <section>
        <h2>Преимущества</h2>

        <div class="advantages-grid">

            <div class="advantage-card">
                <h3>Высокая производительность</h3>
                <p>
                    Многолазерная система обеспечивает высокую скорость производства.
                </p>
            </div>

            <div class="advantage-card">
                <h3>Точность печати</h3>
                <p>
                    Высокая повторяемость и стабильность геометрии изделий.
                </p>
            </div>

            <div class="advantage-card">
                <h3>Широкий выбор материалов</h3>
                <p>
                    Поддержка титана, стали, алюминия и Inconel.
                </p>
            </div>

            <div class="advantage-card">
                <h3>Промышленная надежность</h3>
                <p>
                    Оборудование рассчитано на непрерывную эксплуатацию.
                </p>
            </div>

        </div>
    </section>

    <!-- TILE BLOCKS -->
    <section>

        <div class="tile-grid">

            <div class="tile large">
                <h2>О технологии SLM</h2>

                <p>
                    Технология селективного лазерного плавления позволяет создавать 
                    металлические изделия путем послойного плавления порошка лазером.
                </p>
            </div>

            <div class="tile">
                <h2>Применение</h2>

                <p>
                    Авиация, машиностроение, медицина, энергетика, НИОКР.
                </p>
            </div>

            <div class="tile">
                <h2>Материалы</h2>

                <p>
                    Нержавеющая сталь, титановые сплавы, алюминий, Inconel.
                </p>
            </div>

            <div class="tile large">
                <h2>Кейсы</h2>

                <p>
                    Производство импеллеров, теплообменников, функциональных деталей 
                    и изделий сложной геометрии.
                </p>
            </div>

        </div>

    </section>

    <!-- ХАРАКТЕРИСТИКИ -->
    <section>

        <h2>Технические характеристики</h2>

        <table class="specs-table">

            <tr>
                <td>Размер камеры</td>
                <td>400 × 400 × 450 мм</td>
            </tr>

            <tr>
                <td>Количество лазеров</td>
                <td>4 × 500 W</td>
            </tr>

            <tr>
                <td>Толщина слоя</td>
                <td>20–80 мкм</td>
            </tr>

            <tr>
                <td>Материалы</td>
                <td>Ti / SS / Al / Inconel</td>
            </tr>

        </table>

    </section>

    <!-- VIDEO -->
    <section>

        <h2>Видео работы оборудования</h2>

        <div class="video-box">
            Видео / iframe
        </div>

    </section>

    <!-- ПО -->
    <section>

        <div class="tile">

            <h2>Программное обеспечение</h2>

            <p>
                Подготовка моделей, slicing, мониторинг процесса 
                и удаленное управление оборудованием.
            </p>

        </div>

    </section>

    <!-- СЕРВИС -->
    <section>

        <div class="tile">

            <h2>Сервис и поддержка</h2>

            <p>
                Пусконаладка, обучение персонала, техническая поддержка, 
                сервисное сопровождение и поставка расходных материалов.
            </p>

        </div>

    </section>

    <!-- FAQ -->
    <section>

        <h2>FAQ</h2>

        <div class="faq-list">

            <div class="faq-item">
                <h3>Какие материалы поддерживаются?</h3>

                <p>
                    Титан, нержавеющая сталь, алюминий, Inconel 
                    и другие металлические сплавы.
                </p>
            </div>

            <div class="faq-item">
                <h3>Проводится ли обучение?</h3>

                <p>
                    Да, специалисты компании проводят обучение операторов 
                    и технологов работе с оборудованием.
                </p>
            </div>

            <div class="faq-item">
                <h3>Есть ли сервисная поддержка?</h3>

                <p>
                    Предоставляется полный цикл технического сопровождения оборудования.
                </p>
            </div>

        </div>

    </section>

    <!-- CTA -->
    <section>

        <div class="cta">

            <h2>Получите консультацию по подбору оборудования</h2>

            <p>
                Наши специалисты помогут подобрать промышленное решение 
                под ваши производственные задачи.
            </p>

            <a href="#" class="btn">
                Запросить коммерческое предложение
            </a>

        </div>

    </section>

</div>
```
